What is the output of the following code snippet?
#include <stdio.h>
main(){ int x = 65, *p = &x; void *q = p; char *r = q; printf("%c", *r); }

What is the output of the following C-program?
#define CUBE(x) (x*x*x)
int main(){ int a, b=3; a=CUBE(b++); printf("%d, %d\n", a, b); return 0; }
